    deadline = t0 + budget_seconds * 0.90
    rng = np.random.default_rng(1234567)

    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = np.maximum(s, 0.0)
            best_r = _R(best)
    if best is None:
        best = np.ones(50)
        best_r = _R(best)

    # Exact polish of start
    if time.process_time() < deadline:
        seg = min(deadline, time.process_time() + budget_seconds * 0.08)
        h, r = _refine(best.copy(), seg, _obj_exact, 2000)
        if r > best_r:
            best, best_r = h, r

    # Try higher-resolution grids: finer grids can sharpen the peak.
    for scale in [1.5, 2.0, 3.0]:
        if time.process_time() >= deadline:
            break
        n_new = min(4000, int(best.size * scale))
        if n_new <= best.size:
            continue
        cand = _grow(best, n_new)
        seg = min(deadline, time.process_time() + budget_seconds * 0.07)
        h, r = _refine(cand, seg, _obj_exact, 1500)
        if r > best_r:
            best, best_r = h, r
            if h.size > 2000:
                for nn in [h.size // 2, h.size // 4]:
                    if nn < 20:
                        break
                    hc = _resample(h, nn)
                    rc = _R(hc)
                    if rc >= r - 1e-4:
                        best, best_r = hc, rc
                        break

