        seg = min(deadline, time.process_time() + budget_seconds * 0.04)
        h, r = _refine(best.copy(), seg, lambda x, pp=p: _obj_smooth(x, pp), 1200)
        if r > best_r:
            best, best_r = h, r

    # Perturb + refine loop
    it = 0
    while time.process_time() < deadline:
        it += 1
        mode = it % 8
        if mode == 0:
            trial = best * (1.0 + 0.002 * rng.standard_normal(best.size))
        elif mode == 1:
            w = int(rng.integers(2, max(3, best.size // 8)))
            trial = _smooth(best, w)
        elif mode == 2:
            trial = best + 0.001 * best.mean() * rng.standard_normal(best.size)
        elif mode == 3:
            n_new = max(10, int(best.size * (0.6 + 0.6 * rng.random())))
            small = _resample(best, n_new)
            small = _smooth(small, max(1, n_new // 12))
            trial = _resample(small, best.size)
        elif mode == 4:
            trial = best.copy()
            lo = int(rng.integers(0, best.size))
            length = int(rng.integers(2, max(3, best.size // 5)))
            hi = min(best.size, lo + length)
