    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    mx = Lc.max()
    if mx <= 0:
        return 0.0, Lc
    return sq / (s * s * mx), Lc


def _grad_sq(h, L):
    c = np.zeros_like(L)
    c[:-1] += (2.0 * L[:-1] + L[1:]) / 3.0
    c[1:] += (L[:-1] + 2.0 * L[1:]) / 3.0
    return 2.0 * np.correlate(c[1:-1], h, mode='valid')


