            hi = int(rng.integers(0, max(1, best.size // 20)))
            if lo + hi < best.size - 4:
                trial = np.concatenate((np.zeros(lo), best[lo:best.size - hi], np.zeros(hi)))
        elif mode == 10:
            f = int(rng.integers(2, 5))
            cand = _downsample_pool(best, f)
            if cand.size < 20:
                continue
            trial = cand
        else:
            f = int(rng.integers(2, 5))
            w = int(rng.integers(2, 6))
            cand = _downsample_pool(_smooth(best, w), f)
            if cand.size < 20:
                continue
            trial = cand

        trial = np.maximum(trial, 0.0)
        if trial.sum() <= 0:
            continue
        seg = min(deadline, time.process_time() + 0.4)
        h, r = _refine(trial, seg, lambda x: _obj_smooth(x, 120.0), 500)
        if r > best_r:
            if time.process_time() < deadline:
                seg2 = min(deadline, time.process_time() + 0.3)
                h2, r2 = _refine(h.copy(), seg2, _obj_exact, 800)
                if r2 > r:
                    h, r = h2, r2
            if h.size > 100:
                for f in [2, 3, 4]:
                    cand = _downsample_pool(h, f)
                    if cand.size < 20:
                        continue
                    rc = _R(cand)
                    if rc >= r - 5e-4:
                        seg3 = min(deadline, time.process_time() + 0.3)
                        h3, r3 = _refine(cand, seg3, _obj_exact, 600)
                        if r3 > r:
                            h, r = h3, r3
                        break
            best, best_r = h, r

    # Phase 7: final trim + heavy polish
    trimmed = _trim_zeros(best)
    if trimmed.size >= 4 and trimmed.size != best.size:
        rt = _R(trimmed)
        if rt >= best_r - 1e-12:
            best = trimmed
            best_r = rt

    if time.process_time() < deadline:
        seg = min(deadline, time.process_time() + budget_seconds * 0.10)
        h, r = _refine(best.copy(), seg, _obj_exact, 15000)
        if r > best_r:
            best, best_r = h, r

    best = np.maximum(best, 0.0)
    if best.sum() <= 0:
        best = np.ones(50)
    return best
